import{_ as o,o as a,c as t,a0 as r}from"./chunks/framework.tVbs9ddD.js";const p=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),s={name:"explanation/concepts.md"};function d(n,e,c,i,l,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>kuda&#39;s vocabulary is small but load-bearing — most of it is about <em>what a card is allowed to claim</em>.</p><h2 id="entity" tabindex="-1">Entity <a class="header-anchor" href="#entity" aria-label="Permalink to &quot;Entity&quot;">​</a></h2><ul><li><strong>Repo</strong> — the unit of indexing. One <code>.kuda/</code> per checkout.</li><li><strong>Workspace</strong> — a set of sibling repo roots declared in <code>.kuda/workspace.yaml</code> or <code>[workspace]</code> in <code>kuda.toml</code>; enables cross-repo queries like <code>dependents</code>.</li><li><strong>Module</strong> — the unit a card describes. Grouped by <em>manifest package name</em>, not directory name, so <code>kuda-docs/</code> (the <code>docs</code> worktree) indexes as <code>kuda-docs</code>, not <code>docs</code>.</li><li><strong>File</strong> — the unit of freshness. Every source file gets a git blob hash; a card&#39;s <code>verify:</code> list names the files an agent must open before trusting it.</li></ul><h2 id="memory-tiers" tabindex="-1">Memory tiers <a class="header-anchor" href="#memory-tiers" aria-label="Permalink to &quot;Memory tiers&quot;">​</a></h2><ul><li><strong>L0 — repo card</strong> (<code>.kuda/index.yaml</code>): the always-load blob. Purpose, module map, commands, provenance. ~1k tokens.</li><li><strong>L1 — module cards</strong> (<code>.kuda/modules/*.yaml</code>): fetched on demand when planning touches a module.</li><li><strong>L1 file cards</strong> (<code>.kuda/files/&lt;module&gt;/*.yaml</code>): per-source-file purpose, opt-in via <code>[summarize] file_cards = true</code>.</li><li><strong>L2 — graph</strong> (<code>.kuda/index.sqlite</code>): symbols, dependency edges both directions, per-file hashes. Gitignored, rebuildable — derived state, never reviewed prose.</li><li><strong>L3 — the source</strong>: the only truth. Memory is an index <em>into</em> code, never a replacement.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to &quot;Provenance&quot;">​</a></h2><p>Every card carries <code>{files, hashes, commit_sha, generator}</code>. <code>kuda status</code> re-hashes and reports drift per card — staleness is a diff, not a guess. Cards are committed so humans review them in git diffs; the L2 graph is ignored because it regenerates.</p><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to &quot;Ports&quot;">​</a></h2><ul><li><strong>extract</strong> — mechanical symbol/edge pull. Adapters: <code>manifest</code> (package graph, free), <code>treesitter</code> (grammar+query data), <code>lsp</code> (a real language server, strongest where present).</li><li><strong>summarize</strong> — extraction → card prose. <code>template</code> is deterministic; <code>llm</code>/<code>acp</code> tiers are opt-in.</li><li><strong>store</strong> — where cards and the graph live (<code>sqlite</code> today).</li><li><strong>vcs</strong> — commit-sha and blob-hash provenance (<code>git</code> today).</li></ul><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><p><code>kuda</code> CLI for humans and scripts; <code>kuda mcp</code> for MCP-speaking agents; <code>kuda acp</code> to drive an external agent as the summarizer. All read the same <code>.kuda/</code> artifacts.</p>',12)])])}const h=o(s,[["render",d]]);export{p as __pageData,h as default};
